/* APLUS AI Tutor Database V1 - P6 Synthesis and Transformation Question Bank */
const APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_QUESTION_BANK = [
{id:'P6-ST-0001',type:'synthesis',skill:'because',question:'Combine the sentences using because: The match was cancelled. It was raining heavily.',answer:'The match was cancelled because it was raining heavily.',acceptedPatterns:['The match was cancelled because it was raining heavily.'],explanation:'Because introduces the reason for the cancellation.',difficulty:1},
{id:'P6-ST-0002',type:'synthesis',skill:'although',question:'Combine the sentences using although: Amir was tired. He continued working.',answer:'Although Amir was tired, he continued working.',acceptedPatterns:['Although Amir was tired, he continued working.','Amir continued working although he was tired.'],explanation:'Although joins contrasting ideas.',difficulty:1},
{id:'P6-ST-0003',type:'synthesis',skill:'so that',question:'Combine the sentences using so that: Lina spoke loudly. Everyone could hear her.',answer:'Lina spoke loudly so that everyone could hear her.',acceptedPatterns:['Lina spoke loudly so that everyone could hear her.'],explanation:'So that expresses purpose or intended result.',difficulty:2},
{id:'P6-ST-0004',type:'synthesis',skill:'relative clause',question:'Combine the sentences using who: The boy won the race. He is my neighbour.',answer:'The boy who won the race is my neighbour.',acceptedPatterns:['The boy who won the race is my neighbour.'],explanation:'Who introduces a relative clause referring to a person.',difficulty:1},
{id:'P6-ST-0005',type:'synthesis',skill:'relative clause',question:'Combine the sentences using which: I bought a camera. It takes clear photographs.',answer:'I bought a camera which takes clear photographs.',acceptedPatterns:['I bought a camera which takes clear photographs.','I bought a camera that takes clear photographs.'],explanation:'Which can introduce a relative clause referring to a thing.',difficulty:2},
{id:'P6-ST-0006',type:'synthesis',skill:'after',question:'Combine the sentences using after: Mei finished her homework. She watched television.',answer:'After Mei finished her homework, she watched television.',acceptedPatterns:['After Mei finished her homework, she watched television.','Mei watched television after she finished her homework.'],explanation:'After shows that one action happened before another.',difficulty:2},
{id:'P6-ST-0007',type:'synthesis',skill:'before',question:'Combine the sentences using before: Tom packed his bag. He left home.',answer:'Before Tom left home, he packed his bag.',acceptedPatterns:['Before Tom left home, he packed his bag.','Tom packed his bag before he left home.'],explanation:'Before shows the order of two actions.',difficulty:1},
{id:'P6-ST-0008',type:'synthesis',skill:'while',question:'Combine the sentences using while: I was reading. My sister was drawing.',answer:'I was reading while my sister was drawing.',acceptedPatterns:['I was reading while my sister was drawing.','While my sister was drawing, I was reading.'],explanation:'While shows simultaneous actions.',difficulty:1},
{id:'P6-ST-0009',type:'synthesis',skill:'conditional',question:'Rewrite using if: Study hard and you will improve your results.',answer:'If you study hard, you will improve your results.',acceptedPatterns:['If you study hard, you will improve your results.','You will improve your results if you study hard.'],explanation:'The first conditional uses present simple in the if-clause and will plus the base verb in the result clause.',difficulty:2},
{id:'P6-ST-0010',type:'synthesis',skill:'unless',question:'Rewrite using unless: You will miss the bus if you do not hurry.',answer:'You will miss the bus unless you hurry.',acceptedPatterns:['You will miss the bus unless you hurry.'],explanation:'Unless means if not.',difficulty:3},
{id:'P6-ST-0011',type:'transformation',skill:'reported speech',question:'Rewrite in reported speech: Ben said, "I am busy."',answer:'Ben said that he was busy.',acceptedPatterns:['Ben said that he was busy.'],explanation:'Am changes to was after the past reporting verb said.',difficulty:2},
{id:'P6-ST-0012',type:'transformation',skill:'reported speech',question:'Rewrite in reported speech: Sara said, "I have finished my work."',answer:'Sara said that she had finished her work.',acceptedPatterns:['Sara said that she had finished her work.'],explanation:'Present perfect changes to past perfect after a past reporting verb in standard reported speech.',difficulty:3},
{id:'P6-ST-0013',type:'transformation',skill:'reported question',question:'Rewrite in reported speech: "Where do you live?" Mum asked me.',answer:'Mum asked me where I lived.',acceptedPatterns:['Mum asked me where I lived.'],explanation:'Reported questions use statement word order.',difficulty:3},
{id:'P6-ST-0014',type:'transformation',skill:'reported command',question:'Rewrite in reported speech: The teacher said, "Close the door."',answer:'The teacher told us to close the door.',acceptedPatterns:['The teacher told us to close the door.','The teacher told me to close the door.'],explanation:'A reported command can use told plus object plus to-infinitive.',difficulty:2},
{id:'P6-ST-0015',type:'transformation',skill:'passive voice',question:'Rewrite in the passive voice: The pupils cleaned the classroom.',answer:'The classroom was cleaned by the pupils.',acceptedPatterns:['The classroom was cleaned by the pupils.'],explanation:'The object of the active sentence becomes the subject of the passive sentence.',difficulty:2},
{id:'P6-ST-0016',type:'transformation',skill:'passive voice',question:'Rewrite in the passive voice: The chef prepares the meals every morning.',answer:'The meals are prepared by the chef every morning.',acceptedPatterns:['The meals are prepared by the chef every morning.'],explanation:'Use the present passive for a regular action.',difficulty:2},
{id:'P6-ST-0017',type:'transformation',skill:'comparative',question:'Rewrite using as...as: The blue box is heavier than the red box.',answer:'The red box is not as heavy as the blue box.',acceptedPatterns:['The red box is not as heavy as the blue box.'],explanation:'A comparative can be changed to a negative as...as structure.',difficulty:3},
{id:'P6-ST-0018',type:'transformation',skill:'comparative',question:'Rewrite using not as...as: Jane is taller than May.',answer:'May is not as tall as Jane.',acceptedPatterns:['May is not as tall as Jane.'],explanation:'The shorter person can be described with not as + adjective + as.',difficulty:2},
{id:'P6-ST-0019',type:'transformation',skill:'too to',question:'Rewrite using too...to: The bag is so heavy that I cannot carry it.',answer:'The bag is too heavy for me to carry.',acceptedPatterns:['The bag is too heavy for me to carry.'],explanation:'Too plus adjective plus for + person + to-infinitive expresses an excessive degree.',difficulty:3},
{id:'P6-ST-0020',type:'transformation',skill:'enough to',question:'Rewrite using enough: The boy is strong. He can lift the box.',answer:'The boy is strong enough to lift the box.',acceptedPatterns:['The boy is strong enough to lift the box.'],explanation:'Adjective plus enough plus to-infinitive expresses sufficient ability.',difficulty:2},
{id:'P6-ST-0021',type:'synthesis',skill:'despite',question:'Combine the sentences using despite: It was raining. The hikers continued their walk.',answer:'Despite the rain, the hikers continued their walk.',acceptedPatterns:['Despite the rain, the hikers continued their walk.','The hikers continued their walk despite the rain.'],explanation:'Despite is followed by a noun phrase or gerund phrase and shows contrast.',difficulty:3},
{id:'P6-ST-0022',type:'synthesis',skill:'because of',question:'Combine the sentences using because of: The flight was delayed. There was heavy fog.',answer:'The flight was delayed because of the heavy fog.',acceptedPatterns:['The flight was delayed because of the heavy fog.','Because of the heavy fog, the flight was delayed.'],explanation:'Because of is followed by a noun phrase.',difficulty:2},
{id:'P6-ST-0023',type:'transformation',skill:'verb pattern',question:'Rewrite using enjoy: I like reading mystery stories.',answer:'I enjoy reading mystery stories.',acceptedPatterns:['I enjoy reading mystery stories.'],explanation:'Enjoy can express liking and is followed by a gerund.',difficulty:1},
{id:'P6-ST-0024',type:'transformation',skill:'purpose',question:'Rewrite using in order to: She went to the library because she wanted to borrow a book.',answer:'She went to the library in order to borrow a book.',acceptedPatterns:['She went to the library in order to borrow a book.'],explanation:'In order to introduces purpose.',difficulty:2},
{id:'P6-ST-0025',type:'transformation',skill:'connector transformation',question:'Rewrite using therefore: The road was flooded, so the buses stopped running.',answer:'The road was flooded; therefore, the buses stopped running.',acceptedPatterns:['The road was flooded; therefore, the buses stopped running.','The road was flooded. Therefore, the buses stopped running.'],explanation:'Therefore links a cause to its result.',difficulty:3},
{id:'P6-ST-0026',type:'transformation',skill:'embedded question',question:'Rewrite as an embedded question: Where is the nearest clinic?',answer:'Could you tell me where the nearest clinic is?',acceptedPatterns:['Could you tell me where the nearest clinic is?','Do you know where the nearest clinic is?'],explanation:'An embedded question uses statement word order.',difficulty:3},
{id:'P6-ST-0027',type:'synthesis',skill:'and',question:'Combine the sentences using and: Ali opened the box. Ali removed the books.',answer:'Ali opened the box and removed the books.',acceptedPatterns:['Ali opened the box and removed the books.'],explanation:'The repeated subject can be omitted in the second coordinated verb phrase.',difficulty:1},
{id:'P6-ST-0028',type:'synthesis',skill:'so',question:'Combine the sentences using so: The shop was closed. We returned home.',answer:'The shop was closed, so we returned home.',acceptedPatterns:['The shop was closed, so we returned home.'],explanation:'So introduces the result of the first clause.',difficulty:1},
{id:'P6-ST-0029',type:'transformation',skill:'modal transformation',question:'Rewrite using must: It is necessary for all visitors to sign in.',answer:'All visitors must sign in.',acceptedPatterns:['All visitors must sign in.'],explanation:'Must expresses necessity or obligation.',difficulty:1},
{id:'P6-ST-0030',type:'transformation',skill:'modal transformation',question:'Rewrite using may: Perhaps Ella will join us later.',answer:'Ella may join us later.',acceptedPatterns:['Ella may join us later.'],explanation:'May expresses possibility.',difficulty:1},
{id:'P6-ST-0031',type:'synthesis',skill:'so...that',question:'Combine the sentences using so...that: The box was heavy. I could not lift it.',answer:'The box was so heavy that I could not lift it.',acceptedPatterns:['The box was so heavy that I could not lift it.'],explanation:'So + adjective + that expresses a result.',difficulty:2},
{id:'P6-ST-0032',type:'synthesis',skill:'such...that',question:'Combine the sentences using such...that: It was a difficult question. Nobody could answer it.',answer:'It was such a difficult question that nobody could answer it.',acceptedPatterns:['It was such a difficult question that nobody could answer it.'],explanation:'Such + noun phrase + that expresses a result.',difficulty:3},
{id:'P6-ST-0033',type:'transformation',skill:'unless',question:'Rewrite using unless: You cannot enter if you do not have a pass.',answer:'You cannot enter unless you have a pass.',acceptedPatterns:['You cannot enter unless you have a pass.'],explanation:'Unless replaces if...not.',difficulty:2},
{id:'P6-ST-0034',type:'transformation',skill:'because of',question:'Rewrite using because of: The flight was delayed because there was heavy fog.',answer:'The flight was delayed because of the heavy fog.',acceptedPatterns:['The flight was delayed because of the heavy fog.'],explanation:'Because of is followed by a noun phrase.',difficulty:2},
{id:'P6-ST-0035',type:'transformation',skill:'despite',question:'Rewrite using despite: Although he was nervous, he gave the speech.',answer:'Despite being nervous, he gave the speech.',acceptedPatterns:['Despite being nervous, he gave the speech.','He gave the speech despite being nervous.'],explanation:'Despite can be followed by a gerund phrase.',difficulty:3},
{id:'P6-ST-0036',type:'transformation',skill:'active voice',question:'Rewrite in the active voice: The cake was baked by Sarah.',answer:'Sarah baked the cake.',acceptedPatterns:['Sarah baked the cake.'],explanation:'The agent in the passive sentence becomes the subject in the active sentence.',difficulty:2},
{id:'P6-ST-0037',type:'transformation',skill:'reported speech',question:'Rewrite in reported speech: Tom said, "I will finish it tomorrow."',answer:'Tom said that he would finish it the next day.',acceptedPatterns:['Tom said that he would finish it the next day.','Tom said that he would finish it the following day.'],explanation:'Will commonly changes to would and tomorrow changes to the next day after a past reporting verb.',difficulty:3},
{id:'P6-ST-0038',type:'synthesis',skill:'who relative clause',question:'Combine the sentences using who: The doctor helped the child. The doctor works nearby.',answer:'The doctor who helped the child works nearby.',acceptedPatterns:['The doctor who helped the child works nearby.'],explanation:'Who links a person to information about that person.',difficulty:2},
{id:'P6-ST-0039',type:'transformation',skill:'comparative',question:'Rewrite using more...than: The red car is faster than the blue car.',answer:'The blue car is less fast than the red car.',acceptedPatterns:['The blue car is less fast than the red car.'],explanation:'The same comparison can be expressed using less + adjective + than.',difficulty:3},
{id:'P6-ST-0040',type:'transformation',skill:'purpose',question:'Rewrite using so that: I wrote the instructions clearly because everyone needed to understand them.',answer:'I wrote the instructions clearly so that everyone could understand them.',acceptedPatterns:['I wrote the instructions clearly so that everyone could understand them.'],explanation:'So that can express the intended purpose of an action.',difficulty:2}
];
window.APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_QUESTION_BANK = APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_QUESTION_BANK;